            sy=r.get('start_year');ny=r.get('number_of_years');q=r.get('cargoes_per_year')
            if sy is not None and (sy!=int(sy) or not 1900<=sy<=2200):raise ValueError('Invalid first delivery year')
            if ny is not None and (ny!=int(ny) or not 1<=ny<=100):raise ValueError('Duration must be 1-100 years')
