class Handler(BaseHTTPRequestHandler):
    def send(self,status,data,ctype='application/json; charset=utf-8'):
        raw=data.encode('utf-8') if isinstance(data,str) else json.dumps(data,ensure_ascii=False,allow_nan=False).encode('utf-8')
        self.send_response(status);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(raw)));self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff');self.send_header('X-Frame-Options','DENY');self.end_headers();self.wfile.write(raw)
    def allowed_hosts(self):
        hosts={'127.0.0.1:8501','localhost:8501'}
        for key in ('RADIX_PUBLIC_DOMAIN_NAME','RADIX_CANONICAL_DOMAIN_NAME','ALLOWED_HOSTS'):
            for value in os.environ.get(key,'').split(','):
                value=value.strip().lower()
                if value:hosts.add(value)
        return hosts
    def host_ok(self):
        return self.headers.get('Host','').lower() in self.allowed_hosts()
    def origin_ok(self, origin):
        if not origin:return True
        if origin in ('http://127.0.0.1:8501','http://localhost:8501'):return True
        parsed=urlparse(origin)
        return parsed.scheme=='https' and parsed.netloc.lower() in self.allowed_hosts() and parsed.path in ('','/') and not parsed.query and not parsed.fragment
    def do_GET(self):
        try:
            if urlparse(self.path).path=='/healthz':self.send(200,{'status':'ok'});return
            if not self.host_ok():self.send(403,{'error':'Invalid host'});return
            p=urlparse(self.path).path
            if p=='/':self.send(200,HTML.replace('__TOKEN__',TOKEN),'text/html; charset=utf-8')
            elif p=='/api/state':self.send(200,state())
            elif p=='/api/prices':self.send(200,pricing())
            else:self.send(404,{'error':'Not found'})
        except Exception as e:self.send(400,{'error':str(e)})
    def do_POST(self):
        try:
            if not self.host_ok() or self.headers.get('X-ORI-Token')!=TOKEN:raise ValueError('Reload the app: invalid request token')
            origin=self.headers.get('Origin')
            if not self.origin_ok(origin):raise ValueError('Cross-origin write rejected')
            if 'application/json' not in self.headers.get('Content-Type',''):raise ValueError('Expected JSON')
            length=int(self.headers.get('Content-Length','0'))
            if not 0<length<30_000_000:raise ValueError('Request too large')
            b=json.loads(self.rfile.read(length));p=urlparse(self.path).path
            with LOCK:
                if p=='/api/prices/import':
                    raw=base64.b64decode(b['content'],validate=True)
                    if len(raw)>15_000_000:raise ValueError('Maximum workbook size 15 MB')
                    result=parse_workbook(raw,'Imported workbook: '+Path(b.get('name','Prices.xlsx')).name)
                    if CACHE.exists():CACHE.with_suffix('.previous.json').write_bytes(CACHE.read_bytes())
                    atomic(CACHE,result);self.send(200,result);return
                if p=='/api/prices/recover':
                    if CACHE.exists():CACHE.with_suffix('.previous.json').write_bytes(CACHE.read_bytes())
                    atomic(CACHE,SNAPSHOT);self.send(200,SNAPSHOT);return
                old=state()
                if b.get('revision')!=old['revision']:self.send(409,{'error':'Workspace changed in another window. Reload before saving.'});return
                target=None
                if p=='/api/save':n=b['state']
                elif p=='/api/demo':
                    n=copy.deepcopy(old);sample=demo()
                    for c in COLLECTIONS:
                        ids={x['id'] for x in n[c]};n[c].extend(x for x in sample[c] if x['id'] not in ids)
                elif p=='/api/convert':
                    n=copy.deepcopy(old);t=b['type'];i=b['id']
                    if t not in ['insight','idea']:raise ValueError('Unsupported conversion')
                    src=next(x for x in n[TYPES[t]] if x['id']==i);tt='idea' if t=='insight' else 'lead';key='converted_'+tt+'_id'
                    if src.get(key) and any(x['id']==src[key] for x in n[TYPES[tt]]):self.send(200,{'state':old,'target':{'type':tt,'id':src[key]}});return
                    target={'type':tt,'id':uid()};x={'id':target['id'],'title':src['title'],'type':'Idea','status':'Investigate','interesting':src.get('implication','')} if tt=='idea' else {'id':target['id'],'name':src['title'],'kind':'lead','valuation_unit':'$/MMBtu','rationale':src.get('interesting',''),'open_questions':src.get('questions',''),'owner':src.get('owner','')}
                    x['source_ref']={'type':t,'id':i};n[TYPES[tt]].append(x);src[key]=x['id']
                    if t=='idea':src['status']='Converted to lead'
                    for l in list(n['links']):
                        other=l['to'] if l['from']==x['source_ref'] else l['from'] if l['to']==x['source_ref'] else None
                        if other and other['type']=='need':n['links'].append({'id':uid(),'from':other,'to':target,'contribution':l.get('contribution',''),'downside':l.get('downside','')})
                    n['links'].append({'id':uid(),'from':x['source_ref'],'to':target,'contribution':'Source / conversion history, not approval.'})
                else:self.send(404,{'error':'Not found'});return
                result=save(n,old)
            self.send(200,{'state':result,'target':target} if target else result)
        except Exception as e:self.send(400,{'error':str(e)})
    def log_message(self,fmt,*args):print(fmt%args)
def main():
    try:state();server=ThreadingHTTPServer(('0.0.0.0',8501),Handler)
    except Exception as e:raise RuntimeError('Cannot start: check port and data-folder permissions') from e
    print('LNG ORI Workspace v15: http://127.0.0.1:8501\nData:',DATA,'\nCtrl+C to stop.')
    # Browser auto-launch disabled for container deployment.
    try:server.serve_forever()
    except KeyboardInterrupt:pass
    finally:server.server_close()

