def normalise(d):
    n = _v11_previous_normalise(d)
    n['version'] = 11
    return n

def validate(n):
    _v11_previous_validate(n)
    for record in n['records']:
        valuation = record.get('valuation')
        if valuation is None:
            continue
        if not isinstance(valuation, dict):
            raise ValueError('Valuation must be an object')
        for key in ['total_npv_usd', 'npv_per_mmbtu', 'intrinsic_per_mmbtu',
                    'extrinsic_per_mmbtu', 'shipping_cost_per_mmbtu']:
            value = valuation.get(key)
            if value is not None and not finite(value):
                raise ValueError('Invalid valuation number: ' + key)
        shipping = valuation.get('shipping_cost_per_mmbtu')
        if shipping is not None and shipping < 0:
            raise ValueError('Shipping cost assumption must be zero or positive')
        if valuation.get('ie_included', 'Not assessed') not in ['Not assessed', 'On', 'Off']:
            raise ValueError('IE must be On, Off or Not assessed')
        if valuation.get('shipping_boiloff', 'Not assessed') not in ['Not assessed', 'Included', 'Excluded']:
            raise ValueError('Invalid boil-off assumption')
        value_date = valuation.get('valuation_date')
        if value_date:
            dt.date.fromisoformat(value_date)
        for key in ['shipping_route', 'key_assumptions']:
            if valuation.get(key) is not None and not isinstance(valuation[key], str):
                raise ValueError('Assumption notes must be text')
# END LNG ORI V11 VALIDATION


# V12: retain the original data model, including the recoverable deletion archive.
_v12_previous_normalise = normalise
_v12_previous_validate = validate

def normalise(d):
    n = _v12_previous_normalise(d)
    n['version'] = 12
    n.setdefault('recently_deleted_leads', [])
    return n

def validate(n):
    _v12_previous_validate(n)
    trash = n.get('recently_deleted_leads', [])
    if not isinstance(trash, list):
        raise ValueError('Recently deleted leads must be a list')
    seen = set()
    for entry in trash:
        if not isinstance(entry, dict) or not isinstance(entry.get('id'), str):
            raise ValueError('Invalid recently deleted lead entry')
        if entry['id'] in seen:
            raise ValueError('Duplicate recently deleted entry')
        seen.add(entry['id'])
        if not isinstance(entry.get('record'), dict) or not entry['record'].get('id'):
            raise ValueError('Recently deleted lead is missing its original record')
        collections = entry.get('collections', {})
        if not isinstance(collections, dict):
            raise ValueError('Invalid archived follow-up items')
        for key, rows in collections.items():
            if key not in ['actions', 'milestones', 'resources', 'comments', 'links'] or not isinstance(rows, list):
                raise ValueError('Invalid archived collection')
# END LNG ORI V12 VALIDATION


# V13 workflow: source records retained, one lead record across working views.
GATES.update({'cqc': 'CQC', 'customisation_meeting': 'Customisation meeting'})
_v13_previous_normalise = normalise
_v13_previous_validate = validate

def normalise(d):
    n = _v13_previous_normalise(d)
    n['version'] = 13
    for record in n['records']:
        record.setdefault('workflow_state', 'current' if record.get('kind') == 'current' or record.get('lifecycle') == 'Signed' else 'lead')
        if record.get('workflow_state') != 'archived' and (record.get('kind') == 'current' or record.get('lifecycle') == 'Signed'):
            record['kind'] = 'current'
            record['lifecycle'] = 'Signed'
            record['workflow_state'] = 'current'
        record.setdefault('responsibilities', {})
        record.setdefault('workflow_history', [])
    return n

def validate(n):
    _v13_previous_validate(n)
    for record in n['records']:
        state = record.get('workflow_state', 'lead')
        if state not in ['lead', 'current', 'archived']:
            raise ValueError('Unknown workflow state')
        if state == 'archived' and not str(record.get('archive_reason', '')).strip():
            raise ValueError('Archived leads need a reason')
        if state == 'current' and (record.get('kind') != 'current' or record.get('lifecycle') != 'Signed'):
            raise ValueError('Current-contract workflow state requires a signed current record')
        region = record.get('qualified_region', '')
        if region not in ['', 'Europe', 'Asia', 'US', 'South America', 'Other / unassigned']:
            raise ValueError('Invalid qualified-lead geography')
        stage = record.get('workflow_stage', '')
        if stage not in ['', 'CQC', 'Customisation', 'DGA', 'DGB', 'DGC']:
            raise ValueError('Invalid DG workflow stage')
        responsibilities = record.get('responsibilities', {})
        if not isinstance(responsibilities, dict):
            raise ValueError('Responsibilities must be an object')
        for key, value in responsibilities.items():
            if value is not None and not isinstance(value, str):
                raise ValueError('Responsible people must be entered as text')
        if not isinstance(record.get('workflow_history', []), list):
            raise ValueError('Workflow history must be a list')
        valuation = record.get('valuation') or {}
        for key in ['portfolio_value_per_mmbtu', 'portfolio_value_usd']:
            value = valuation.get(key)
            if value is not None and not finite(value):
                raise ValueError('Invalid Portfolio Value: ' + key)
        signed_date = record.get('signed_date')
        if signed_date:
            actual = dt.date.fromisoformat(signed_date)
            if actual > dt.date.today():
                raise ValueError('Actual signing date cannot be in the future')
# END LNG ORI V13 VALIDATION


# V14: recoverable contract deletion; no change to pricing or qualification rules.
