# V15: additional need specifications and explicit workspace roster only.
V15_WORLD_NOTICE = '''Offline world geometry derived from Natural Earth low-resolution
country polygons bundled with pyogrio. Simplified representative country points,
not ports or exact project sites. ISO country-code names from pycountry data.
No remote tiles or external transmission of portfolio data is required. Unmapped
countries are listed rather than assigned guessed coordinates.'''
_v15_previous_normalise = normalise
_v15_previous_validate = validate

def normalise(d):
    n = _v15_previous_normalise(d)
    n['version'] = 15
    for need in n.get('needs', []):
        need.setdefault('portfolio_spec', {})
    original_settings = d.get('settings', {})
    if isinstance(original_settings, dict) and 'workflow_team' in original_settings:
        n.setdefault('settings', {})['workflow_team'] = copy.deepcopy(original_settings['workflow_team'])
    return n

def validate(n):
    _v15_previous_validate(n)
    themes = ['', 'Portfolio Growth', 'Risk Management', 'Value Optimisation',
              'Regas', 'European Sales', 'Asia / JKTC Sales',
              'Supply Diversification', 'Shipping & Flexibility', 'Other / Uncategorised']
    for need in n.get('needs', []):
        spec = need.get('portfolio_spec', {})
        if not isinstance(spec, dict):
            raise ValueError('Portfolio need requirements must be an object')
        if spec.get('theme', '') not in themes:
            raise ValueError('Unknown portfolio need theme')
        for key, value in spec.items():
            if value is not None and not isinstance(value, str):
                raise ValueError('Portfolio need requirement values must be text with explicit units')
    roster = n.get('settings', {}).get('workflow_team')
    if roster is not None:
        if not isinstance(roster, list) or not roster or len(roster) > 100:
            raise ValueError('Workspace roster must contain 1 to 100 people')
        names = set()
        for person in roster:
            if not isinstance(person, dict) or not isinstance(person.get('name'), str) or not person['name'].strip():
                raise ValueError('Roster display names must be non-empty text')
            key = person['name'].strip().casefold()
            if key in names:
                raise ValueError('Roster display names must be unique')
            names.add(key)
            aliases = person.get('aliases', [])
            if not isinstance(aliases, list) or any(not isinstance(a, str) or not a.strip() for a in aliases):
                raise ValueError('Roster aliases must be non-empty text')
# END LNG ORI V15 VALIDATION


