# V16: explicit map coordinates only; all previous validators remain active.
_v16_previous_normalise = normalise
_v16_previous_validate = validate

def normalise(d):
    n = _v16_previous_normalise(d)
    n['version'] = 16
    originals = {x.get('id'): x for x in d.get('records', []) if isinstance(x, dict)}
    for record in n.get('records', []):
        original = originals.get(record.get('id'), {})
        if 'map_locations' in original:
            record['map_locations'] = copy.deepcopy(original['map_locations'])
    return n

def validate(n):
    import math
    _v16_previous_validate(n)
    for record in n.get('records', []):
        points = record.get('map_locations', [])
        if not isinstance(points, list) or len(points) > 100:
            raise ValueError('Map locations must be a list of at most 100 named points per record')
        ids = set()
        for point in points:
            if not isinstance(point, dict):
                raise ValueError('Each map location must be an object')
            pid = point.get('id')
            if not isinstance(pid, str) or not pid.strip() or pid in ids:
                raise ValueError('Map location IDs must be non-empty and unique within each record')
            ids.add(pid)
            if not isinstance(point.get('name'), str) or not point['name'].strip():
                raise ValueError('Every map location requires a name')
            for key, lower, upper in [('latitude', -90, 90), ('longitude', -180, 180)]:
                value = point.get(key)
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not lower <= value <= upper:
                    raise ValueError('Map ' + key + ' must be finite decimal degrees in the valid range')
# END LNG ORI V16 VALIDATION

